/**
 * One-time bootstrap for the externally managed Entra application that fronts
 * the agent backend. Normal azd provision/deploy does not call this script.
 *
 * The Application (client) ID is generated by Entra. The caller chooses the
 * Application ID URI used by token clients, and it does not need to contain the
 * generated client ID.
 */

import { execFileSync } from "node:child_process";
import { randomUUID } from "node:crypto";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const AZURE_CLI_CLIENT_ID = "04b07795-8ddb-461a-bbee-02f9e1bf7b46";
export const DELEGATED_SCOPE_VALUE = "access_as_user";
export const APPLICATION_ROLE_VALUE = "access_as_application";

interface OAuth2Scope {
  id: string;
  value: string;
  isEnabled: boolean;
  type?: string;
  adminConsentDisplayName?: string;
  adminConsentDescription?: string;
  userConsentDisplayName?: string;
  userConsentDescription?: string;
}

interface PreAuthorizedApplication {
  appId: string;
  delegatedPermissionIds: string[];
}

interface AppRole {
  id: string;
  value: string;
  isEnabled: boolean;
  allowedMemberTypes: string[];
  displayName: string;
  description: string;
}

interface ApplicationRecord {
  id: string;
  appId: string;
  displayName: string;
  api?: {
    oauth2PermissionScopes?: OAuth2Scope[];
    preAuthorizedApplications?: PreAuthorizedApplication[];
    requestedAccessTokenVersion?: number | null;
    [key: string]: unknown;
  };
  appRoles?: AppRole[];
}

export interface ApplicationPatch {
  signInAudience: "AzureADMyOrg";
  identifierUris: string[];
  api: NonNullable<ApplicationRecord["api"]>;
  appRoles: AppRole[];
}

export function withoutPreAuthorizedApplications(
  patch: ApplicationPatch,
): ApplicationPatch {
  const { preAuthorizedApplications: _preAuthorizedApplications, ...api } = patch.api;
  return { ...patch, api };
}

export interface BootstrapArgs {
  displayName: string;
  applicationIdUri: string;
  applicationClientId?: string;
  tenantId?: string;
  serviceManagementReference?: string;
  callerClientIds: string[];
  dryRun: boolean;
}

function requireValue(argv: string[], index: number, flag: string): string {
  const value = argv[index + 1]?.trim();
  if (!value || value.startsWith("--")) {
    throw new Error(`${flag} requires a value`);
  }
  return value;
}

export function parseArgs(argv: string[]): BootstrapArgs {
  const args: BootstrapArgs = {
    displayName: "",
    applicationIdUri: "",
    callerClientIds: [],
    dryRun: false,
  };

  for (let index = 0; index < argv.length; index++) {
    const flag = argv[index];
    switch (flag) {
      case "--display-name":
        args.displayName = requireValue(argv, index, flag);
        index++;
        break;
      case "--application-id-uri":
        args.applicationIdUri = requireValue(argv, index, flag).replace(/\/+$/, "");
        index++;
        break;
      case "--application-client-id":
        args.applicationClientId = requireValue(argv, index, flag);
        index++;
        break;
      case "--tenant-id":
        args.tenantId = requireValue(argv, index, flag);
        index++;
        break;
      case "--service-management-reference":
        args.serviceManagementReference = requireValue(argv, index, flag);
        index++;
        break;
      case "--caller-client-id":
        args.callerClientIds.push(requireValue(argv, index, flag));
        index++;
        break;
      case "--dry-run":
        args.dryRun = true;
        break;
      case "--help":
      case "-h":
        printUsage();
        process.exit(0);
      default:
        throw new Error(`Unknown argument '${flag}'`);
    }
  }

  if (!args.displayName) throw new Error("--display-name is required");
  if (!args.applicationIdUri) throw new Error("--application-id-uri is required");
  if (!/^(api|https):\/\//i.test(args.applicationIdUri)) {
    throw new Error("--application-id-uri must start with api:// or https://");
  }
  return args;
}

export function buildApplicationPatch(
  application: Pick<ApplicationRecord, "api" | "appRoles">,
  applicationIdUri: string,
): { patch: ApplicationPatch; scopeId: string; appRoleId: string } {
  const api = { ...(application.api ?? {}) };
  const scopes = [...(api.oauth2PermissionScopes ?? [])];
  const preAuthorizedApplications = (api.preAuthorizedApplications ?? []).map((entry) => ({
    ...entry,
    delegatedPermissionIds: [...entry.delegatedPermissionIds],
  }));
  const appRoles = [...(application.appRoles ?? [])];

  const scopeIndex = scopes.findIndex((candidate) => candidate.value === DELEGATED_SCOPE_VALUE);
  const existingScope = scopeIndex >= 0 ? scopes[scopeIndex] : undefined;
  const scope: OAuth2Scope = {
    ...existingScope,
    id: existingScope?.id ?? randomUUID(),
    value: DELEGATED_SCOPE_VALUE,
    type: "User",
    isEnabled: true,
    adminConsentDisplayName: "Access Azure SDK QA agent as the signed-in user",
    adminConsentDescription:
      "Allows the app to call the Azure SDK QA agent server on behalf of the signed-in user.",
    userConsentDisplayName: "Access Azure SDK QA agent on your behalf",
    userConsentDescription:
      "Allows the app to call the Azure SDK QA agent server on your behalf.",
  };
  if (scopeIndex >= 0) scopes[scopeIndex] = scope;
  else scopes.push(scope);

  const cliAuthorization = preAuthorizedApplications.find(
    (entry) => entry.appId.toLowerCase() === AZURE_CLI_CLIENT_ID,
  );
  if (cliAuthorization) {
    if (!cliAuthorization.delegatedPermissionIds.includes(scope.id)) {
      cliAuthorization.delegatedPermissionIds.push(scope.id);
    }
  } else {
    preAuthorizedApplications.push({
      appId: AZURE_CLI_CLIENT_ID,
      delegatedPermissionIds: [scope.id],
    });
  }

  const appRoleIndex = appRoles.findIndex(
    (candidate) => candidate.value === APPLICATION_ROLE_VALUE,
  );
  const existingAppRole = appRoleIndex >= 0 ? appRoles[appRoleIndex] : undefined;
  const appRole: AppRole = {
    ...existingAppRole,
    id: existingAppRole?.id ?? randomUUID(),
    value: APPLICATION_ROLE_VALUE,
    isEnabled: true,
    allowedMemberTypes: ["Application"],
    displayName: "Access Azure SDK QA agent as an application",
    description: "Allows a managed identity to call the Azure SDK QA agent server.",
  };
  if (appRoleIndex >= 0) appRoles[appRoleIndex] = appRole;
  else appRoles.push(appRole);

  return {
    patch: {
      signInAudience: "AzureADMyOrg",
      identifierUris: [applicationIdUri],
      api: {
        ...api,
        requestedAccessTokenVersion: 2,
        oauth2PermissionScopes: scopes,
        preAuthorizedApplications,
      },
      appRoles,
    },
    scopeId: scope.id,
    appRoleId: appRole.id,
  };
}

function runAz(args: string[]): string {
  return execFileSync("az", args, {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "inherit"],
  }).trim();
}

function runAzJson<T>(args: string[]): T {
  return JSON.parse(runAz([...args, "--output", "json"])) as T;
}

function ensureTenant(expectedTenantId?: string): void {
  const actualTenantId = runAz(["account", "show", "--query", "tenantId", "--output", "tsv"]);
  if (expectedTenantId && actualTenantId.toLowerCase() !== expectedTenantId.toLowerCase()) {
    throw new Error(
      `Azure CLI is signed into tenant '${actualTenantId}', expected '${expectedTenantId}'.`,
    );
  }
}

function findOrCreateApplication(args: BootstrapArgs): ApplicationRecord {
  if (args.applicationClientId) {
    return runAzJson<ApplicationRecord>([
      "ad", "app", "show", "--id", args.applicationClientId,
    ]);
  }

  const matches = runAzJson<ApplicationRecord[]>([
    "ad", "app", "list", "--display-name", args.displayName,
  ]).filter((application) => application.displayName === args.displayName);
  if (matches.length > 1) {
    throw new Error(
      `Multiple applications are named '${args.displayName}'. Re-run with --application-client-id.`,
    );
  }
  if (matches.length === 1) return matches[0];

  const body: Record<string, string> = {
    displayName: args.displayName,
    signInAudience: "AzureADMyOrg",
  };
  if (args.serviceManagementReference) {
    body.serviceManagementReference = args.serviceManagementReference;
  }
  return runAzJson<ApplicationRecord>([
    "rest",
    "--method", "POST",
    "--url", "https://graph.microsoft.com/v1.0/applications",
    "--headers", "Content-Type=application/json",
    "--body", JSON.stringify(body),
  ]);
}

function ensureServicePrincipal(applicationClientId: string): { id: string; appId: string } {
  const existing = runAzJson<Array<{ id: string; appId: string }>>([
    "ad", "sp", "list", "--filter", `appId eq '${applicationClientId}'`,
  ]);
  if (existing.length > 0) return existing[0];
  return runAzJson<{ id: string; appId: string }>([
    "ad", "sp", "create", "--id", applicationClientId,
  ]);
}

function assignApplicationRole(
  callerClientId: string,
  resourceServicePrincipalId: string,
  appRoleId: string,
): void {
  const caller = runAzJson<{ id: string; displayName: string }>([
    "ad", "sp", "show", "--id", callerClientId,
  ]);
  const assignments = runAzJson<{ value: Array<{ appRoleId: string; resourceId: string }> }>([
    "rest",
    "--method", "GET",
    "--url",
    `https://graph.microsoft.com/v1.0/servicePrincipals/${caller.id}/appRoleAssignments` +
      "?$select=appRoleId,resourceId",
  ]).value;
  if (assignments.some(
    (assignment) => assignment.appRoleId === appRoleId &&
      assignment.resourceId === resourceServicePrincipalId,
  )) {
    console.log(`[create-entra-app] Application role already assigned to ${caller.displayName}.`);
    return;
  }

  runAz([
    "rest",
    "--method", "POST",
    "--url", `https://graph.microsoft.com/v1.0/servicePrincipals/${caller.id}/appRoleAssignments`,
    "--headers", "Content-Type=application/json",
    "--body", JSON.stringify({
      principalId: caller.id,
      resourceId: resourceServicePrincipalId,
      appRoleId,
    }),
    "--output", "none",
  ]);
  console.log(`[create-entra-app] Assigned application role to ${caller.displayName}.`);
}

function printUsage(): void {
  console.log([
    "Usage: npx tsx scripts/create-entra-app.ts --display-name <name> --application-id-uri <uri> [options]",
    "",
    "Options:",
    "  --application-client-id <id>       Configure an existing application instead of creating one",
    "  --tenant-id <id>                   Require the current Azure CLI tenant to match",
    "  --service-management-reference <id>  Include the tenant-required reference when creating",
    "  --caller-client-id <id>            Assign access_as_application; may be repeated",
    "  --dry-run                          Print the intended configuration without Azure calls",
    "  -h, --help                         Show this help",
  ].join("\n"));
}

export function main(argv: string[]): void {
  const args = parseArgs(argv);
  if (args.dryRun) {
    console.log(`[create-entra-app] Would create or configure '${args.displayName}'.`);
    console.log(`[create-entra-app] Application ID URI: ${args.applicationIdUri}`);
    console.log(`[create-entra-app] Pre-authorized client: Azure CLI (${AZURE_CLI_CLIENT_ID})`);
    console.log(`[create-entra-app] Caller role assignments: ${args.callerClientIds.length}`);
    return;
  }

  ensureTenant(args.tenantId);
  let application = findOrCreateApplication(args);
  application = runAzJson<ApplicationRecord>(["ad", "app", "show", "--id", application.appId]);
  const { patch, scopeId, appRoleId } = buildApplicationPatch(application, args.applicationIdUri);

  runAz([
    "rest",
    "--method", "PATCH",
    "--url", `https://graph.microsoft.com/v1.0/applications/${application.id}`,
    "--headers", "Content-Type=application/json",
    "--body", JSON.stringify(withoutPreAuthorizedApplications(patch)),
    "--output", "none",
  ]);
  runAz([
    "rest",
    "--method", "PATCH",
    "--url", `https://graph.microsoft.com/v1.0/applications/${application.id}`,
    "--headers", "Content-Type=application/json",
    "--body", JSON.stringify({ api: patch.api }),
    "--output", "none",
  ]);
  const servicePrincipal = ensureServicePrincipal(application.appId);

  for (const callerClientId of new Set(args.callerClientIds)) {
    assignApplicationRole(callerClientId, servicePrincipal.id, appRoleId);
  }

  console.log("");
  console.log("[create-entra-app] Bootstrap complete. Pin these values in environment-suite.yaml:");
  console.log(`  serverApplicationClientId: '${application.appId}'`);
  console.log(`  serverApplicationIdUri: '${args.applicationIdUri}'`);
  console.log(`  # delegated scope ID: ${scopeId}`);
  console.log(`  # application role ID: ${appRoleId}`);
  console.log(`  # resource service-principal ID: ${servicePrincipal.id}`);
}

const invokedPath = process.argv[1] ? resolve(process.argv[1]) : "";
if (invokedPath === fileURLToPath(import.meta.url)) {
  try {
    main(process.argv.slice(2));
  } catch (error) {
    console.error(`[create-entra-app] FAILED: ${error instanceof Error ? error.message : error}`);
    process.exit(1);
  }
}